//! Differential tests for unit `celt_decoder` (celt/celt_decoder.c): the CELT decoder vs the C
//! oracle, bit-exact on PCM output, return codes, final range and the complete decoder state
//! after every call, on long packet streams generated by the C CELT encoder (all frame sizes,
//! mono/stereo and channel conversions, CBR/VBR from tiny to maximal budgets, transient and
//! tonal signals with the post-filter, intensity/dual stereo, hybrid start band 17 on a shared
//! range decoder, end band limits, 48/24/16/12/8 kHz output, packet loss (noise and pitch PLC),
//! corrupted packets, accumulation, resets), plus direct tests of the static helpers
//! (`tf_decode`, `deemphasis`, `celt_synthesis`, `celt_plc_pitch_search`) and the CTLs. QEXT
//! (96 kHz and 48 kHz extension payloads) and custom modes (`opus_custom_decode*`) run with
//! their features.
//!
//! Shared by the float and the fixed-point builds (`fixed-point`, `fixed-res24`, with or
//! without `qext` / `custom-modes`): the C encoder of the matching oracle produces the packets
//! (float test signals converted with `FLOAT2RES`), the helper inputs are generated as float
//! values and converted to the build's types, and every comparison (PCM as `opus_res`, final
//! range, complete decoder state) is bit-exact.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::too_many_arguments,
    clippy::excessive_precision,
    reason = "test code: failures should panic"
)]

use opusorus::celt::arch::{CeltGlog, CeltNorm, CeltSig, OpusVal16};
use opusorus::celt::celt_decoder::*;
use opusorus::celt::entdec::EcDec;
use opusorus::celt::modes::opus_custom_mode_create;
use opusorus::celt::static_modes::CeltMode;
#[cfg(all(feature = "custom-modes", not(feature = "disable-float-api")))]
use opusorus_conformance::assert_bits_eq_f32;
use opusorus_conformance::{Rng, assert_slice_eq, signals};
use opusorus_oracle::celt_decoder::{self as c, CeltDecState, CeltEnc, Res, StateVal};
use opusorus_oracle::sys;

// ---------------------------------------------------------------------------------------------
// Build-generic values
// ---------------------------------------------------------------------------------------------

/// Bit pattern of a value, for bit-exact comparisons of float and integer data alike.
trait Bits: Copy + core::fmt::Debug {
    fn bits(self) -> u64;
}
impl Bits for f32 {
    fn bits(self) -> u64 {
        u64::from(self.to_bits())
    }
}
impl Bits for i32 {
    fn bits(self) -> u64 {
        u64::from(self as u32)
    }
}
impl Bits for i16 {
    fn bits(self) -> u64 {
        u64::from(self as u16)
    }
}

/// Asserts that two slices are bit-identical.
#[track_caller]
fn assert_v<T: Bits>(what: &str, rust: &[T], c: &[T]) {
    assert_eq!(rust.len(), c.len(), "{what}: length mismatch");
    if let Some(i) = rust.iter().zip(c).position(|(a, b)| a.bits() != b.bits()) {
        panic!(
            "{what}: first mismatch at {i}: rust={:?} c={:?}",
            rust[i], c[i]
        );
    }
}

/// Scales `x` by `2^q` with rounding and saturation to `[-lim, lim]` (fixed-point inputs).
#[cfg(feature = "fixed-point")]
fn fx(x: f32, q: i32, lim: i64) -> i64 {
    ((f64::from(x) * (1i64 << q) as f64).round() as i64).clamp(-lim, lim)
}

/// An `opus_res` from a float sample in [-1, 1] (`FLOAT2RES`-like; the float build keeps it).
#[cfg(not(feature = "fixed-point"))]
const fn res(x: f32) -> Res {
    x
}
#[cfg(feature = "fixed-res24")]
fn res(x: f32) -> Res {
    fx(x, 23, (1 << 23) - 1) as i32
}
#[cfg(all(feature = "fixed-point", not(feature = "fixed-res24")))]
fn res(x: f32) -> Res {
    fx(x, 15, 32767) as i16
}
/// A `celt_sig` from a value in 16-bit PCM units (`SIG_SHIFT` above them in the fixed-point
/// build, saturated to `SIG_SAT` like the decoder's signals).
#[cfg(not(feature = "fixed-point"))]
const fn sig(x: f32) -> CeltSig {
    x
}
#[cfg(feature = "fixed-point")]
fn sig(x: f32) -> CeltSig {
    fx(x, 12, 536_870_911) as i32
}
/// A `celt_norm` from a float value (Q24 in the fixed-point build).
#[cfg(not(feature = "fixed-point"))]
const fn nrm(x: f32) -> CeltNorm {
    x
}
#[cfg(feature = "fixed-point")]
fn nrm(x: f32) -> CeltNorm {
    fx(x, 24, 1 << 30) as i32
}
/// A `celt_glog` from a value in log2 units (Q24 in the fixed-point build).
#[cfg(not(feature = "fixed-point"))]
const fn glog(x: f32) -> CeltGlog {
    x
}
#[cfg(feature = "fixed-point")]
fn glog(x: f32) -> CeltGlog {
    fx(x, 24, 1 << 30) as i32
}
/// A `Vec` of `n` build-typed values made by `f` from `rng`.
fn gen_vals<T>(n: usize, rng: &mut Rng, mut f: impl FnMut(&mut Rng) -> T) -> Vec<T> {
    (0..n).map(|_| f(rng)).collect()
}

/// Amplitude of the random normalised spectrum of the `celt_synthesis` tests.
const XAMP: f32 = 1.0;
/// Amplitude of the random band energies (log2 units) of the `celt_synthesis` tests.
const EAMP: f32 = 12.0;

/// Amplitude of the random de-emphasis memories for input amplitude `amp`: the fixed-point
/// decoder's memory is `coef0*SATURATE(x+mem)`, well below `SIG_SAT`, so `x + mem` cannot
/// overflow (100000 PCM units).
#[cfg(feature = "fixed-point")]
const fn mem_amp(amp: f32) -> f32 {
    amp.min(100_000.0)
}
#[cfg(not(feature = "fixed-point"))]
const fn mem_amp(amp: f32) -> f32 {
    amp
}

// CELT encoder requests (celt/celt.h).
const CELT_SET_PREDICTION_REQUEST: i32 = 10002;

// ---------------------------------------------------------------------------------------------
// Rust state dump (same layout as oracle_cd_state in csrc/celt_decoder.c)
// ---------------------------------------------------------------------------------------------

fn rust_state(d: &CeltDecoder<'_>) -> CeltDecState {
    #[cfg(feature = "qext")]
    let qext_scale = d.qext_scale;
    #[cfg(not(feature = "qext"))]
    let qext_scale = 1;
    let ints = [
        d.overlap,
        d.channels,
        d.stream_channels,
        d.downsample,
        d.start,
        d.end,
        d.signalling,
        d.disable_inv,
        d.complexity,
        qext_scale,
        d.rng as i32,
        d.error,
        d.last_pitch_index,
        d.loss_duration,
        d.plc_duration,
        d.last_frame_type,
        d.skip_plc,
        d.postfilter_period,
        d.postfilter_period_old,
        d.postfilter_tapset,
        d.postfilter_tapset_old,
        d.prefilter_and_fold,
    ];
    let mut vals: Vec<StateVal> = vec![
        StateVal::from(d.postfilter_gain),
        StateVal::from(d.postfilter_gain_old),
        StateVal::from(d.preemph_mem_d[0]),
        StateVal::from(d.preemph_mem_d[1]),
    ];
    #[cfg(feature = "qext")]
    vals.extend(d.qext_old_band_e.iter().map(|&v| StateVal::from(v)));
    for a in [
        &d.decode_mem,
        &d.old_ebands,
        &d.old_log_e,
        &d.old_log_e2,
        &d.background_log_e,
    ] {
        vals.extend(a.iter().map(|&v| StateVal::from(v)));
    }
    vals.extend(d.lpc.iter().map(|&v| StateVal::from(v)));
    CeltDecState { ints, vals }
}

#[track_caller]
fn assert_state_eq(ctx: &str, r: &CeltDecState, c: &CeltDecState) {
    assert_slice_eq(&format!("{ctx}: state ints"), &r.ints, &c.ints);
    assert_v(&format!("{ctx}: state values"), &r.vals, &c.vals);
}

// ---------------------------------------------------------------------------------------------
// Decoder pair
// ---------------------------------------------------------------------------------------------

/// A Rust and a C decoder driven in lockstep.
struct Pair<'m> {
    r: CeltDecoder<'m>,
    c: c::CeltDec,
    channels: usize,
    frames: usize,
    cov: Coverage,
}

/// Decoder paths seen by a [`Pair`] (sanity checks that the streams exercise what they claim).
#[derive(Debug, Default, Clone, Copy)]
struct Coverage {
    /// Frames decoded from a packet.
    normal: usize,
    /// Frames concealed with the noise PLC.
    plc_noise: usize,
    /// Frames concealed with the pitch PLC.
    plc_periodic: usize,
    /// Decoded frames with the post-filter on.
    postfilter: usize,
    /// Frames with non-zero output.
    nonzero: usize,
}

impl Pair<'static> {
    /// `celt_decoder_init(fs, channels)` on both sides, signalling off (as the Opus decoder).
    fn new(fs: i32, channels: i32) -> Self {
        let r = CeltDecoder::celt_decoder_init(fs, channels).unwrap();
        let c = c::CeltDec::new(fs, channels).unwrap();
        let mut p = Pair {
            r,
            c,
            channels: channels as usize,
            frames: 0,
            cov: Coverage::default(),
        };
        p.set(CELT_SET_SIGNALLING_REQUEST, 0);
        p.check_state("init");
        p
    }
}

impl Pair<'_> {
    /// Issues a SET ctl on both and compares the results.
    fn set(&mut self, request: i32, value: i32) {
        let rc = self.c.ctl_set(request, value);
        let rr = self.r.ctl_set(request, value);
        assert_eq!(code(rr.map(|()| 0)), rc, "ctl_set({request}, {value})");
    }

    fn check_state(&mut self, ctx: &str) {
        assert_state_eq(ctx, &rust_state(&self.r), &self.c.state());
    }

    /// Decodes one frame on both sides and compares everything.
    fn decode(
        &mut self,
        data: Option<&[u8]>,
        len: i32,
        frame_size: i32,
        accum: bool,
        qext: Option<&[u8]>,
        rng: &mut Rng,
        ctx: &str,
    ) -> i32 {
        let n_out = frame_size.max(0) as usize * self.channels;
        let mut pc = vec![Res::default(); n_out];
        if accum {
            for v in pc.iter_mut() {
                *v = res(0.5 * rng.f32_sym());
            }
        }
        let mut pr = pc.clone();
        let rc = self.c.decode(data, len, &mut pc, frame_size, accum, qext);
        let rr = rs_decode(&mut self.r, data, len, &mut pr, frame_size, accum, qext);
        let ctx = format!("{ctx} frame {}", self.frames);
        assert_eq!(code(rr), rc, "{ctx}: return value");
        assert_v(&format!("{ctx}: pcm"), &pr, &pc);
        assert_eq!(
            self.r.final_range(),
            self.c.ctl_get(sys::OPUS_GET_FINAL_RANGE_REQUEST).1 as u32,
            "{ctx}: final range"
        );
        self.check_state(&ctx);
        self.frames += 1;
        if rc > 0 {
            match self.r.last_frame_type {
                FRAME_NORMAL => self.cov.normal += 1,
                FRAME_PLC_NOISE => self.cov.plc_noise += 1,
                FRAME_PLC_PERIODIC => self.cov.plc_periodic += 1,
                _ => {}
            }
            if self.r.last_frame_type == FRAME_NORMAL
                && self.r.postfilter_gain != OpusVal16::default()
            {
                self.cov.postfilter += 1;
            }
            if pr.iter().any(|&v| v != Res::default()) {
                self.cov.nonzero += 1;
            }
        }
        rc
    }
}

const fn code(r: opusorus::Result<i32>) -> i32 {
    match r {
        Ok(v) => v,
        Err(e) => e.code(),
    }
}

#[allow(unused_variables, reason = "qext is only passed with the qext feature")]
fn rs_decode(
    d: &mut CeltDecoder<'_>,
    data: Option<&[u8]>,
    len: i32,
    pcm: &mut [Res],
    frame_size: i32,
    accum: bool,
    qext: Option<&[u8]>,
) -> opusorus::Result<i32> {
    #[cfg(feature = "qext")]
    {
        d.celt_decode_with_ec_dred(data, len, pcm, frame_size, None, accum, qext)
    }
    #[cfg(not(feature = "qext"))]
    {
        assert!(qext.is_none());
        d.celt_decode_with_ec(data, len, pcm, frame_size, None, accum)
    }
}

// ---------------------------------------------------------------------------------------------
// Signals and packet generation
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Sig {
    Music,
    Speech,
    Noise,
    /// Tone plus periodic clicks (transients) and silent gaps.
    Clicks,
    /// Pure harmonic tone (pitch post-filter, periodic PLC).
    Tone,
    Silence,
}

fn gen_signal(sig: Sig, n: usize, ch: usize, fs: u32, seed: u64) -> Vec<f32> {
    match sig {
        Sig::Music => signals::music_like(n, ch, fs, seed),
        Sig::Speech => signals::speech_like(n, ch, fs, seed),
        Sig::Noise => signals::noise(n, ch, 0.3, seed),
        Sig::Silence => vec![0.0; n * ch],
        Sig::Tone | Sig::Clicks => {
            let mut rng = Rng::new(seed);
            let f0 = 90.0 + (seed % 200) as f64;
            let mut out = Vec::with_capacity(n * ch);
            for i in 0..n {
                let t = i as f64 / fs as f64;
                let mut v = 0.0f64;
                for k in 1..6 {
                    v += 0.12 / k as f64 * (2.0 * core::f64::consts::PI * f0 * k as f64 * t).sin();
                }
                if sig == Sig::Clicks {
                    let pos = i % (fs as usize / 7);
                    if pos < 40 {
                        v += 0.8 * rng.f32_sym() as f64;
                    }
                    if (i / (fs as usize / 3)) % 4 == 3 {
                        v *= 0.001;
                    }
                }
                for cch in 0..ch {
                    out.push((v * (1.0 - 0.2 * cch as f64)) as f32);
                }
            }
            out
        }
    }
}

/// Parses the output of the C encoder: `(main payload, QEXT payload)`.
fn split_packet(out: &[u8], ret: usize) -> (Vec<u8>, Option<Vec<u8>>) {
    let pkt = &out[1..1 + ret];
    if out[0] & 3 == 3 {
        assert_eq!(pkt[0], 0x41);
        let mut pos = 1;
        let mut padding = 0usize;
        loop {
            let p = pkt[pos] as usize;
            pos += 1;
            padding += if p == 255 { 254 } else { p };
            if p != 255 {
                break;
            }
        }
        let main_len = ret - pos - padding;
        let main = pkt[pos..pos + main_len].to_vec();
        let ext = &pkt[pos + main_len..];
        assert_eq!(ext[0], 124 << 1);
        (main, Some(ext[1..].to_vec()))
    } else {
        (pkt.to_vec(), None)
    }
}

/// Encoder configuration for a stream.
#[derive(Debug, Clone, Copy)]
struct EncCfg {
    fs: i32,
    channels: i32,
    frame_size: i32,
    /// Packet size in bytes (CBR) or the max size (VBR).
    nbytes: i32,
    /// VBR bitrate (0 = CBR).
    vbr_bitrate: i32,
    complexity: i32,
    start: i32,
    end: i32,
    sig: Sig,
    qext: bool,
    loss_perc: i32,
    prediction: i32,
}

impl EncCfg {
    const fn new(channels: i32, frame_size: i32, nbytes: i32, sig: Sig) -> Self {
        Self {
            fs: 48000,
            channels,
            frame_size,
            nbytes,
            vbr_bitrate: 0,
            complexity: 10,
            start: 0,
            end: 21,
            sig,
            qext: false,
            loss_perc: 0,
            prediction: 2,
        }
    }
}

fn make_encoder(cfg: &EncCfg) -> CeltEnc {
    let mut e = CeltEnc::new(cfg.fs, cfg.channels);
    assert_eq!(e.ctl(sys::OPUS_SET_COMPLEXITY_REQUEST, cfg.complexity), 0);
    if cfg.vbr_bitrate > 0 {
        assert_eq!(e.ctl(sys::OPUS_SET_VBR_REQUEST, 1), 0);
        assert_eq!(e.ctl(sys::OPUS_SET_BITRATE_REQUEST, cfg.vbr_bitrate), 0);
    }
    if cfg.start != 0 {
        assert_eq!(e.ctl(CELT_SET_START_BAND_REQUEST, cfg.start), 0);
    }
    if cfg.end != 21 {
        assert_eq!(e.ctl(CELT_SET_END_BAND_REQUEST, cfg.end), 0);
    }
    if cfg.qext {
        assert_eq!(e.ctl(sys::OPUS_SET_QEXT_REQUEST, 1), 0);
    }
    if cfg.loss_perc != 0 {
        assert_eq!(
            e.ctl(sys::OPUS_SET_PACKET_LOSS_PERC_REQUEST, cfg.loss_perc),
            0
        );
    }
    if cfg.prediction != 2 {
        assert_eq!(e.ctl(CELT_SET_PREDICTION_REQUEST, cfg.prediction), 0);
    }
    e
}

/// A generated packet: main payload plus optional QEXT payload.
type Packet = (Vec<u8>, Option<Vec<u8>>);

/// Encodes `nframes` frames of the configured signal with the C encoder.
fn gen_packets(cfg: &EncCfg, nframes: usize, seed: u64) -> Vec<Packet> {
    let mut e = make_encoder(cfg);
    let fsz = cfg.frame_size as usize;
    let ch = cfg.channels as usize;
    let pcm = gen_signal(cfg.sig, fsz * nframes, ch, cfg.fs as u32, seed);
    let mut rng = Rng::new(seed ^ 0x55);
    (0..nframes)
        .map(|i| {
            // Vary the CBR budget a little to exercise more allocations.
            let nbytes = if cfg.vbr_bitrate == 0 && cfg.nbytes > 8 {
                (cfg.nbytes + rng.range_i32(-3, 3)).clamp(2, if cfg.qext { 3825 } else { 1275 })
            } else {
                cfg.nbytes
            };
            let (ret, out) = e.encode(
                &pcm[i * fsz * ch..(i + 1) * fsz * ch],
                cfg.frame_size,
                nbytes,
            );
            assert!(ret > 0, "encode failed: {ret} ({cfg:?})");
            split_packet(&out, ret as usize)
        })
        .collect()
}

/// Loss patterns.
#[derive(Debug, Clone, Copy)]
enum Loss {
    None,
    /// Independent random losses with the given percentage.
    Random(i32),
    /// Bursts of up to the given length.
    Bursts(usize),
    /// Every other packet lost (skip_plc stays set).
    Alternate,
}

fn loss_mask(loss: Loss, n: usize, rng: &mut Rng) -> Vec<bool> {
    let mut m = vec![false; n];
    match loss {
        Loss::None => {}
        Loss::Random(p) => {
            for v in m.iter_mut() {
                *v = rng.range_i32(0, 99) < p;
            }
        }
        Loss::Bursts(max) => {
            let mut i = 3;
            while i < n {
                let len = rng.range_i32(1, max as i32) as usize;
                for v in m.iter_mut().skip(i).take(len) {
                    *v = true;
                }
                i += len + rng.range_i32(1, 12) as usize;
            }
        }
        Loss::Alternate => {
            for (i, v) in m.iter_mut().enumerate() {
                *v = i % 2 == 1;
            }
        }
    }
    m
}

/// Decodes a packet stream on a pair with the given loss pattern.
fn run_stream(
    pair: &mut Pair<'_>,
    pkts: &[Packet],
    out_frame: i32,
    loss: Loss,
    seed: u64,
    ctx: &str,
) {
    let mut rng = Rng::new(seed);
    let mask = loss_mask(loss, pkts.len(), &mut rng);
    for (i, (main, ext)) in pkts.iter().enumerate() {
        if mask[i] {
            pair.decode(None, 0, out_frame, false, None, &mut rng, ctx);
        } else {
            let ret = pair.decode(
                Some(main),
                main.len() as i32,
                out_frame,
                false,
                ext.as_deref(),
                &mut rng,
                ctx,
            );
            assert_eq!(ret, out_frame, "{ctx}: frame {i} decoded size");
        }
    }
}

// ---------------------------------------------------------------------------------------------
// CTLs, init, errors
// ---------------------------------------------------------------------------------------------

#[test]
fn init_and_ctls() {
    for &fs in &[48000, 24000, 16000, 12000, 8000] {
        for ch in 1..=2 {
            let mut p = Pair::new(fs, ch);
            let ctx = format!("fs={fs} ch={ch}");
            // GET requests.
            for req in [
                OPUS_GET_COMPLEXITY_REQUEST,
                CELT_GET_AND_CLEAR_ERROR_REQUEST,
                OPUS_GET_LOOKAHEAD_REQUEST,
                OPUS_GET_PITCH_REQUEST,
                OPUS_GET_FINAL_RANGE_REQUEST,
                OPUS_GET_PHASE_INVERSION_DISABLED_REQUEST,
            ] {
                let (rc, vc) = p.c.ctl_get(req);
                let rr = p.r.ctl_get(req);
                assert_eq!(code(rr), if rc == 0 { vc } else { rc }, "{ctx}: get {req}");
            }
            assert!(p.c.get_mode_ok());
            assert!(core::ptr::eq(
                p.r.mode(),
                opus_custom_mode_create(48000, 960).unwrap()
            ));
            // SET requests, valid and invalid values.
            for (req, vals) in [
                (OPUS_SET_COMPLEXITY_REQUEST, &[-1, 0, 5, 10, 11][..]),
                (CELT_SET_START_BAND_REQUEST, &[-1, 0, 17, 20, 21, 0][..]),
                (CELT_SET_END_BAND_REQUEST, &[0, 1, 13, 21, 22, 21][..]),
                (CELT_SET_CHANNELS_REQUEST, &[0, 1, 2, 3, ch][..]),
                (CELT_SET_SIGNALLING_REQUEST, &[0, 1, 0][..]),
                (
                    OPUS_SET_PHASE_INVERSION_DISABLED_REQUEST,
                    &[-1, 0, 1, 2][..],
                ),
            ] {
                for &v in vals {
                    p.set(req, v);
                    p.check_state(&format!("{ctx}: set {req}={v}"));
                }
            }
            for req in [
                OPUS_GET_COMPLEXITY_REQUEST,
                OPUS_GET_PHASE_INVERSION_DISABLED_REQUEST,
            ] {
                let (rc, vc) = p.c.ctl_get(req);
                assert_eq!(rc, 0);
                assert_eq!(p.r.ctl_get(req).unwrap(), vc);
            }
            assert_eq!(p.r.lookahead(), p.c.ctl_get(OPUS_GET_LOOKAHEAD_REQUEST).1);
            // Unknown requests.
            for req in [4000, 4002, 10002, 12345] {
                assert_eq!(p.c.ctl_set(req, 0), sys::OPUS_UNIMPLEMENTED);
                assert_eq!(p.r.ctl_set(req, 0), Err(opusorus::Error::Unimplemented));
                assert_eq!(p.r.ctl_get(req), Err(opusorus::Error::Unimplemented));
            }
            p.set(OPUS_RESET_STATE, 0);
            p.check_state(&format!("{ctx}: reset"));
        }
    }
    // Invalid init.
    assert_eq!(
        CeltDecoder::celt_decoder_init(48000, 3).err(),
        Some(opusorus::Error::BadArg)
    );
    assert_eq!(c::CeltDec::new(48000, 3).err(), Some(sys::OPUS_BAD_ARG));
    assert!(CeltDecoder::celt_decoder_init(48000, 0).is_err());
    assert!(celt_decoder_get_size(2) > celt_decoder_get_size(1));
}

#[test]
fn error_returns() {
    let mut rng = Rng::new(7);
    let pkts = gen_packets(&EncCfg::new(2, 960, 160, Sig::Music), 4, 1);
    let mut p = Pair::new(48000, 2);
    let data = &pkts[0].0;
    // Frame sizes that are not a CELT frame size.
    for fsz in [0, 100, 121, 1920, -960] {
        p.decode(
            Some(data),
            data.len() as i32,
            fsz,
            false,
            None,
            &mut rng,
            "bad frame size",
        );
    }
    // Lengths out of range.
    let big = vec![0u8; 1300];
    p.decode(Some(&big), 1276, 960, false, None, &mut rng, "len 1276");
    p.decode(Some(&big), -1, 960, false, None, &mut rng, "len -1");
    p.decode(None, -1, 960, false, None, &mut rng, "NULL len -1");
    p.decode(None, 1276, 960, false, None, &mut rng, "NULL len 1276");
    // Rust-only guards.
    let mut small = vec![Res::default(); 100];
    assert_eq!(
        p.r.celt_decode_with_ec(Some(data), data.len() as i32, &mut small, 960, None, false),
        Err(opusorus::Error::BadArg)
    );
    assert_eq!(
        p.r.celt_decode_with_ec(
            Some(&data[..3]),
            10,
            &mut vec![Res::default(); 1920],
            960,
            None,
            false
        ),
        Err(opusorus::Error::BadArg)
    );
    // The decoder still works after errors.
    for (m, _) in &pkts {
        p.decode(
            Some(m),
            m.len() as i32,
            960,
            false,
            None,
            &mut rng,
            "after errors",
        );
    }
}

