#[test]
fn streams_frame_sizes_and_budgets() {
    let mut seed = 1u64;
    for &ch in &[1, 2] {
        for &fsz in &[120, 240, 480, 960] {
            for &(nbytes, vbr) in &[
                (2, 0),
                (5, 0),
                (12, 0),
                (40, 0),
                (0, 24000),
                (160, 0),
                (0, 96000),
                (400, 0),
                (1275, 0),
            ] {
                let sig = [
                    Sig::Music,
                    Sig::Speech,
                    Sig::Clicks,
                    Sig::Noise,
                    Sig::Tone,
                    Sig::Silence,
                ][seed as usize % 6];
                let mut cfg = EncCfg::new(ch, fsz, if vbr > 0 { 1275 } else { nbytes }, sig);
                cfg.vbr_bitrate = vbr;
                cfg.complexity = [10, 5, 0, 8][seed as usize % 4];
                let nframes = (19200 / fsz as usize).clamp(20, 80);
                let pkts = gen_packets(&cfg, nframes, seed);
                let mut p = Pair::new(48000, ch);
                run_stream(&mut p, &pkts, fsz, Loss::None, seed, &format!("{cfg:?}"));
                seed += 1;
            }
        }
    }
}

#[test]
fn streams_long_with_state_evolution() {
    // Long streams: post-filter (voiced/tonal), transients, energy prediction.
    for (i, &(ch, fsz, sig, nbytes, vbr)) in [
        (1, 960, Sig::Speech, 0, 32000),
        (2, 960, Sig::Music, 0, 128000),
        (2, 480, Sig::Clicks, 120, 0),
        (1, 240, Sig::Tone, 60, 0),
        (2, 120, Sig::Speech, 0, 64000),
    ]
    .iter()
    .enumerate()
    {
        let mut cfg = EncCfg::new(ch, fsz, if vbr > 0 { 1275 } else { nbytes }, sig);
        cfg.vbr_bitrate = vbr;
        let nframes = 48000 * 3 / fsz as usize;
        let pkts = gen_packets(&cfg, nframes, 100 + i as u64);
        let mut p = Pair::new(48000, ch);
        run_stream(&mut p, &pkts, fsz, Loss::None, 7, &format!("long {cfg:?}"));
        let cov = p.cov;
        assert_eq!(cov.normal, nframes, "{cov:?}");
        assert!(cov.nonzero > nframes * 9 / 10, "{cov:?}");
        if matches!(sig, Sig::Speech | Sig::Tone) {
            assert!(
                cov.postfilter > nframes / 20,
                "post-filter rarely on: {cov:?}"
            );
        }
    }
}

