#[test]
fn streams_hybrid_shared_range_decoder() {
    let mut seed = 1100u64;
    for &ch in &[1, 2] {
        for &fsz in &[480, 960] {
            for &(end, nbytes) in &[(19, 60), (21, 90), (21, 30), (20, 40)] {
                let mut cfg = EncCfg::new(ch, fsz, nbytes, Sig::Speech);
                cfg.start = 17;
                cfg.end = end;
                let mut e = make_encoder(&cfg);
                let mut p = Pair::new(48000, ch);
                p.set(CELT_SET_START_BAND_REQUEST, 17);
                p.set(CELT_SET_END_BAND_REQUEST, end);
                let pcm = gen_signal(Sig::Speech, fsz as usize * 30, ch as usize, 48000, seed);
                let mut rng = Rng::new(seed);
                let fsu = fsz as usize * ch as usize;
                for f in 0..30 {
                    // "SILK" symbols first.
                    let nsym = rng.range_i32(0, nbytes / 4) as usize;
                    let fts: Vec<u32> = (0..nsym).map(|_| rng.range_i32(2, 5000) as u32).collect();
                    let vals: Vec<u32> = fts.iter().map(|&ft| rng.next_u32() % ft).collect();
                    let (ret, out) =
                        e.encode_shared(&pcm[f * fsu..(f + 1) * fsu], fsz, nbytes, &fts, &vals);
                    assert!(ret > 0, "hybrid encode {ret}");
                    let data = &out[..ret as usize];
                    let ctx = format!("hybrid ch={ch} fsz={fsz} end={end} frame {f}");
                    if rng.range_i32(0, 9) == 0 {
                        p.decode(None, 0, fsz, false, None, &mut rng, &ctx);
                        continue;
                    }
                    let accum = rng.range_i32(0, 3) == 0;
                    let mut pc: Vec<Res> = gen_vals(fsu, &mut rng, |r| res(r.f32_sym()));
                    let mut pr = pc.clone();
                    let (rc, vc, ecc) = p.c.decode_shared(data, &mut pc, fsz, accum, &fts);
                    assert_eq!(vc, vals, "{ctx}: SILK symbols");
                    let mut d = EcDec::new(data);
                    let vr: Vec<u32> = fts.iter().map(|&ft| d.dec_uint(ft)).collect();
                    assert_eq!(vr, vals);
                    let rr = p.r.celt_decode_with_ec(
                        Some(data),
                        data.len() as i32,
                        &mut pr,
                        fsz,
                        Some(&mut d),
                        accum,
                    );
                    assert_eq!(code(rr), rc, "{ctx}: ret");
                    assert_v(&ctx, &pr, &pc);
                    assert_eq!(
                        [d.rng, d.tell() as u32, d.tell_frac(), d.error as u32],
                        ecc,
                        "{ctx}: shared ec"
                    );
                    p.check_state(&ctx);
                }
            }
            seed += 1;
        }
    }
}

#[test]
fn streams_packet_loss() {
    let mut seed = 1300u64;
    let mut total = Coverage::default();
    for &ch in &[1, 2] {
        for &fsz in &[120, 240, 480, 960] {
            for (li, &loss) in [
                Loss::Random(20),
                Loss::Bursts(2),
                Loss::Bursts(12),
                Loss::Alternate,
            ]
            .iter()
            .enumerate()
            {
                let sig = [Sig::Tone, Sig::Speech, Sig::Music, Sig::Clicks][li];
                let cfg = EncCfg::new(ch, fsz, 50 * ch, sig);
                let nframes = (48000 / fsz as usize).max(60);
                let pkts = gen_packets(&cfg, nframes, seed);
                let mut p = Pair::new(48000, ch);
                run_stream(
                    &mut p,
                    &pkts,
                    fsz,
                    loss,
                    seed,
                    &format!("loss {loss:?} {cfg:?}"),
                );
                total.plc_noise += p.cov.plc_noise;
                total.plc_periodic += p.cov.plc_periodic;
                seed += 1;
            }
        }
    }
    assert!(total.plc_noise > 5 && total.plc_periodic > 100, "{total:?}");
    // Loss straight after init (skip_plc = 1) and a very long loss (noise PLC saturation).
    let cfg = EncCfg::new(2, 960, 100, Sig::Tone);
    let pkts = gen_packets(&cfg, 12, 77);
    let mut p = Pair::new(48000, 2);
    let mut rng = Rng::new(1);
    for _ in 0..3 {
        p.decode(None, 0, 960, false, None, &mut rng, "initial loss");
    }
    for (m, _) in &pkts[..4] {
        p.decode(Some(m), m.len() as i32, 960, false, None, &mut rng, "good");
    }
    for _ in 0..40 {
        p.decode(None, 0, 960, false, None, &mut rng, "long loss");
    }
    for (m, _) in &pkts[4..] {
        p.decode(
            Some(m),
            m.len() as i32,
            960,
            false,
            None,
            &mut rng,
            "recovery",
        );
    }
    // Lost frames with a different frame size than the stream, and len <= 1 packets.
    for (i, (m, _)) in pkts.iter().enumerate() {
        p.decode(Some(m), m.len() as i32, 960, false, None, &mut rng, "good2");
        let fsz = [120, 240, 480, 960][i % 4];
        p.decode(Some(&m[..1]), 1, fsz, false, None, &mut rng, "len 1");
        p.decode(Some(m), 0, fsz, false, None, &mut rng, "len 0");
    }
}

/// Many random configurations: channels and channel conversion, frame size, CBR/VBR budget,
/// complexity, end band, output rate, loss pattern, accumulation and resets.
#[test]
fn streams_random_configs() {
    let mut rng = Rng::new(0xC0FFEE);
    let sigs = [
        Sig::Music,
        Sig::Speech,
        Sig::Noise,
        Sig::Clicks,
        Sig::Tone,
        Sig::Silence,
    ];
    let mut total = Coverage::default();
    for iter in 0..800u64 {
        let ch = rng.range_i32(1, 2);
        let dec_ch = if rng.range_i32(0, 4) == 0 { 3 - ch } else { ch };
        let fsz = 120 << rng.range_i32(0, 3);
        let sig = sigs[rng.range_i32(0, sigs.len() as i32 - 1) as usize];
        let mut cfg = EncCfg::new(ch, fsz, 0, sig);
        if rng.range_i32(0, 2) == 0 {
            cfg.vbr_bitrate = rng.range_i32(6000, 256000);
            cfg.nbytes = 1275;
        } else {
            cfg.nbytes = [
                rng.range_i32(2, 30),
                rng.range_i32(20, 200),
                rng.range_i32(100, 1275),
            ][rng.range_i32(0, 2) as usize];
        }
        cfg.complexity = rng.range_i32(0, 10);
        if rng.range_i32(0, 3) == 0 {
            cfg.end = [13, 17, 19, 20][rng.range_i32(0, 3) as usize];
        }
        cfg.prediction = [2, 2, 2, 1, 0][rng.range_i32(0, 4) as usize];
        cfg.loss_perc = [0, 0, 5, 25][rng.range_i32(0, 3) as usize];
        let fs = [48000, 48000, 24000, 16000, 12000, 8000][rng.range_i32(0, 5) as usize];
        let ds = 48000 / fs;
        let loss = [
            Loss::None,
            Loss::Random(10),
            Loss::Random(40),
            Loss::Bursts(3),
            Loss::Bursts(20),
            Loss::Alternate,
        ][rng.range_i32(0, 5) as usize];
        let nframes = rng.range_i32(10, 60) as usize;
        let pkts = gen_packets(&cfg, nframes, iter);
        let mut p = Pair::new(fs, dec_ch);
        if dec_ch != ch {
            p.set(CELT_SET_CHANNELS_REQUEST, ch);
        }
        if cfg.end != 21 {
            p.set(CELT_SET_END_BAND_REQUEST, cfg.end);
        }
        if rng.range_i32(0, 3) == 0 {
            p.set(
                OPUS_SET_PHASE_INVERSION_DISABLED_REQUEST,
                1 - p.r.disable_inv,
            );
        }
        let ctx = format!("random {iter}: dec fs={fs} ch={dec_ch} {loss:?} {cfg:?}");
        let mask = loss_mask(loss, nframes, &mut rng);
        for (i, (m, _)) in pkts.iter().enumerate() {
            let accum = rng.range_i32(0, 5) == 0;
            if mask[i] {
                p.decode(None, 0, fsz / ds, accum, None, &mut rng, &ctx);
            } else {
                p.decode(
                    Some(m),
                    m.len() as i32,
                    fsz / ds,
                    accum,
                    None,
                    &mut rng,
                    &ctx,
                );
            }
            if rng.range_i32(0, 60) == 0 {
                p.set(OPUS_RESET_STATE, 0);
            }
        }
        total.normal += p.cov.normal;
        total.plc_noise += p.cov.plc_noise;
        total.plc_periodic += p.cov.plc_periodic;
        total.postfilter += p.cov.postfilter;
    }
    assert!(
        total.plc_noise > 50 && total.plc_periodic > 100 && total.postfilter > 100,
        "{total:?}"
    );
}

