#[test]
fn streams_corrupted_packets() {
    let mut rng = Rng::new(0xC0);
    for &ch in &[1, 2] {
        for &fsz in &[120, 240, 480, 960] {
            let cfg = EncCfg::new(ch, fsz, 80, Sig::Music);
            let pkts = gen_packets(&cfg, 150, fsz as u64 + ch as u64);
            let mut p = Pair::new(48000, ch);
            for (i, (m, _)) in pkts.iter().enumerate() {
                let mut m = m.clone();
                match i % 5 {
                    0 => {}
                    1 => {
                        // bit flips
                        for _ in 0..rng.range_i32(1, 6) {
                            let b = rng.range_i32(0, m.len() as i32 * 8 - 1) as usize;
                            m[b / 8] ^= 1 << (b % 8);
                        }
                    }
                    2 => {
                        // truncation
                        let l = rng.range_i32(2, m.len() as i32) as usize;
                        m.truncate(l);
                    }
                    3 => rng.fill_bytes(&mut m),
                    _ => {
                        // random length garbage
                        let mut g = vec![0u8; rng.range_i32(2, 1275) as usize];
                        rng.fill_bytes(&mut g);
                        m = g;
                    }
                }
                p.decode(
                    Some(&m),
                    m.len() as i32,
                    fsz,
                    false,
                    None,
                    &mut rng,
                    "corrupt",
                );
                // CELT_GET_AND_CLEAR_ERROR sometimes.
                if i % 7 == 0 {
                    let (rc, vc) = p.c.ctl_get(CELT_GET_AND_CLEAR_ERROR_REQUEST);
                    assert_eq!(rc, 0);
                    assert_eq!(p.r.get_and_clear_error(), vc);
                }
            }
        }
    }
    // Silence flag packets and all-zero / all-ones payloads.
    let mut p = Pair::new(48000, 2);
    for (i, pkt) in [
        vec![0x80u8, 0, 0, 0],
        vec![0xFF; 8],
        vec![0; 8],
        vec![0x7F, 0xFF, 0x00, 0x12],
        vec![0; 1275],
        vec![0xFF; 1275],
    ]
    .iter()
    .enumerate()
    {
        for &fsz in &[120, 960] {
            p.decode(
                Some(pkt),
                pkt.len() as i32,
                fsz,
                false,
                None,
                &mut rng,
                &format!("special {i}"),
            );
        }
    }
}

#[test]
fn streams_accum_and_reset() {
    let mut seed = 1500u64;
    for &ch in &[1, 2] {
        for &fsz in &[240, 960] {
            let cfg = EncCfg::new(ch, fsz, 90, Sig::Speech);
            let pkts = gen_packets(&cfg, 40, seed);
            let mut p = Pair::new(48000, ch);
            let mut rng = Rng::new(seed);
            for (i, (m, _)) in pkts.iter().enumerate() {
                let accum = i % 3 != 0;
                if i % 9 == 4 {
                    p.decode(None, 0, fsz, accum, None, &mut rng, "accum lost");
                } else {
                    p.decode(Some(m), m.len() as i32, fsz, accum, None, &mut rng, "accum");
                }
                if i % 13 == 12 {
                    p.set(OPUS_RESET_STATE, 0);
                    p.check_state("reset");
                }
                if i % 11 == 5 {
                    // Complexity has no effect on the decoder without deep PLC.
                    p.set(OPUS_SET_COMPLEXITY_REQUEST, (i % 11) as i32);
                }
            }
            seed += 1;
        }
    }
}

