#[cfg(feature = "qext")]
#[test]
fn qext_streams() {
    assert!(c::has_qext());
    let mut seed = 2000u64;
    let mut total_ext = 0;
    // 96 kHz mode (with and without extension payload) and 48 kHz with extension payloads.
    for &fs in &[96000, 48000] {
        for &ch in &[1, 2] {
            let base = fs / 400;
            for &lm in &[0, 1, 2, 3] {
                let fsz = base << lm;
                for &(qext, nbytes) in &[(true, 900), (true, 300), (false, 200), (true, 2500)] {
                    let mut cfg = EncCfg::new(ch, fsz, nbytes * (1 << lm) / 8 + 40, Sig::Music);
                    cfg.fs = fs;
                    cfg.qext = qext;
                    cfg.nbytes = cfg.nbytes.min(3825);
                    let pkts = gen_packets(&cfg, 16, seed);
                    let n_ext = pkts.iter().filter(|p| p.1.is_some()).count();
                    if !qext {
                        assert_eq!(n_ext, 0, "qext payloads: {cfg:?}");
                    }
                    total_ext += n_ext;
                    let mut p = Pair::new(fs, ch);
                    run_stream(
                        &mut p,
                        &pkts,
                        fsz,
                        Loss::Random(10),
                        seed,
                        &format!("qext {cfg:?} (ext frames {n_ext})"),
                    );
                    seed += 1;
                }
            }
        }
    }
    assert!(total_ext > 150, "frames with QEXT payloads: {total_ext}");
    // Corrupted extension payloads, and stereo stream decoded to mono.
    let mut cfg = EncCfg::new(2, 1920, 1500, Sig::Clicks);
    cfg.fs = 96000;
    cfg.qext = true;
    let pkts = gen_packets(&cfg, 20, 5);
    assert!(pkts.iter().all(|p| p.1.is_some()));
    let mut rng = Rng::new(3);
    let mut p = Pair::new(96000, 2);
    for (i, (m, e)) in pkts.iter().enumerate() {
        let mut e = e.clone().unwrap();
        if i % 2 == 1 {
            let l = rng.range_i32(0, e.len() as i32) as usize;
            e.truncate(l);
            rng.fill_bytes(&mut e[l / 2..]);
        }
        p.decode(
            Some(m),
            m.len() as i32,
            1920,
            false,
            Some(&e),
            &mut rng,
            "qext corrupt",
        );
    }
    let mut p = Pair::new(96000, 1);
    p.set(CELT_SET_CHANNELS_REQUEST, 2);
    run_stream(&mut p, &pkts, 1920, Loss::Bursts(3), 9, "qext 2->1");
}

