#[cfg(feature = "custom-modes")]
#[test]
fn custom_mode_streams() {
    use opusorus::celt::modes::opus_custom_mode_create_custom;
    assert!(c::has_custom());
    let mut seed = 3000u64;
    let mut modes = vec![
        (48000, 960),
        (48000, 480),
        (44100, 512),
        (32000, 320),
        (16000, 160),
        (8000, 80),
        (24000, 240),
        (12000, 256),
    ];
    if cfg!(feature = "qext") {
        modes.push((96000, 1920));
        modes.push((96000, 1024));
    }
    for &(fs, frame) in &modes {
        let mode = opus_custom_mode_create_custom(fs, frame).unwrap();
        let mode: &CeltMode = &mode;
        for &ch in &[1, 2] {
            let mut e = CeltEnc::new_custom(fs, frame, ch).unwrap();
            let mut cd = c::CeltDec::new_custom(fs, frame, ch).unwrap();
            let mut rd = CustomDecoder::opus_custom_decoder_create(mode, ch).unwrap();
            let ctx = format!("custom fs={fs} frame={frame} ch={ch}");
            assert_state_eq(&ctx, &rust_state(&rd), &cd.state());
            let vbr = seed.is_multiple_of(2);
            if vbr {
                assert_eq!(e.ctl(sys::OPUS_SET_VBR_REQUEST, 1), 0);
                assert_eq!(e.ctl(sys::OPUS_SET_BITRATE_REQUEST, 48000 * ch), 0);
            }
            let cu = ch as usize;
            let max_lm = mode.max_lm;
            let nframes = 40;
            let pcm = gen_signal(
                [Sig::Speech, Sig::Music, Sig::Clicks][seed as usize % 3],
                frame as usize * nframes,
                cu,
                fs as u32,
                seed,
            );
            let mut rng = Rng::new(seed);
            let mut pos = 0usize;
            for f in 0..nframes {
                let lm = rng.range_i32(0, max_lm);
                let fsz = mode.short_mdct_size << lm;
                let nbytes = rng.range_i32(8, 200);
                let (ret, out) = e.encode(&pcm[pos * cu..(pos + fsz as usize) * cu], fsz, nbytes);
                pos += fsz as usize;
                assert!(ret > 0, "{ctx}: custom encode {ret}");
                let mut pkt = out[1..1 + ret as usize].to_vec();
                let lost = f % 9 == 7;
                if f % 11 == 10 {
                    rng.fill_bytes(&mut pkt[1..]);
                }
                let data = if lost { None } else { Some(&pkt[..]) };
                let len = pkt.len() as i32;
                let ctx = format!("{ctx} frame {f} lm={lm}");
                match f % 3 {
                    #[cfg(not(feature = "disable-float-api"))]
                    0 => {
                        let mut pc = vec![0f32; frame as usize * cu];
                        let mut pr = pc.clone();
                        let rc = cd.custom_decode_float(data, len, &mut pc, frame);
                        let rr = rd.opus_custom_decode_float(data, len, &mut pr, frame);
                        assert_eq!(code(rr), rc, "{ctx}: ret");
                        assert_bits_eq_f32(&ctx, &pr, &pc);
                    }
                    1 => {
                        let mut pc = vec![0i16; frame as usize * cu];
                        let mut pr = pc.clone();
                        let rc = cd.custom_decode(data, len, &mut pc, frame);
                        let rr = rd.opus_custom_decode(data, len, &mut pr, frame);
                        assert_eq!(code(rr), rc, "{ctx}: ret");
                        assert_slice_eq(&ctx, &pr, &pc);
                    }
                    _ => {
                        let mut pc = vec![0i32; frame as usize * cu];
                        let mut pr = pc.clone();
                        let rc = cd.custom_decode24(data, len, &mut pc, frame);
                        let rr = rd.opus_custom_decode24(data, len, &mut pr, frame);
                        assert_eq!(code(rr), rc, "{ctx}: ret");
                        assert_slice_eq(&ctx, &pr, &pc);
                    }
                }
                assert_state_eq(&ctx, &rust_state(&rd), &cd.state());
            }
            // Signalling errors: invalid TOC, buffer too small.
            for pkt in [
                vec![0x00u8, 1, 2, 3],
                vec![0xFF, 0x40],
                vec![0xFB, 0x41, 0xFF],
                vec![0xE3],
            ] {
                for &fsz in &[frame, mode.short_mdct_size] {
                    #[cfg(not(feature = "disable-float-api"))]
                    {
                        let mut pc = vec![0f32; frame as usize * cu];
                        let mut pr = pc.clone();
                        let rc = cd.custom_decode_float(Some(&pkt), pkt.len() as i32, &mut pc, fsz);
                        let rr =
                            rd.opus_custom_decode_float(Some(&pkt), pkt.len() as i32, &mut pr, fsz);
                        assert_eq!(code(rr), rc, "{ctx}: signalling error {pkt:?}");
                        assert_bits_eq_f32(&ctx, &pr, &pc);
                    }
                    // DISABLE_FLOAT_API: 24-bit output.
                    #[cfg(feature = "disable-float-api")]
                    {
                        let mut pc = vec![0i32; frame as usize * cu];
                        let mut pr = pc.clone();
                        let rc = cd.custom_decode24(Some(&pkt), pkt.len() as i32, &mut pc, fsz);
                        let rr =
                            rd.opus_custom_decode24(Some(&pkt), pkt.len() as i32, &mut pr, fsz);
                        assert_eq!(code(rr), rc, "{ctx}: signalling error {pkt:?}");
                        assert_slice_eq(&ctx, &pr, &pc);
                    }
                    assert_state_eq(&ctx, &rust_state(&rd), &cd.state());
                }
            }
            seed += 1;
        }
    }
}

/// Custom-mode (signalling) packets carrying a QEXT extension in their padding.
#[cfg(all(feature = "custom-modes", feature = "qext"))]
#[test]
fn custom_mode_qext_signalling() {
    use opusorus::celt::modes::opus_custom_mode_create_custom;
    let mut code3 = 0;
    for &(fs, frame) in &[(48000, 960), (96000, 1920)] {
        let mode = opus_custom_mode_create_custom(fs, frame).unwrap();
        let mode: &CeltMode = &mode;
        for &ch in &[1, 2] {
            let mut e = CeltEnc::new_custom(fs, frame, ch).unwrap();
            assert_eq!(e.ctl(sys::OPUS_SET_QEXT_REQUEST, 1), 0);
            let mut cd = c::CeltDec::new_custom(fs, frame, ch).unwrap();
            let mut rd = CustomDecoder::opus_custom_decoder_create(mode, ch).unwrap();
            let cu = ch as usize;
            let pcm = gen_signal(Sig::Music, frame as usize * 12, cu, fs as u32, 11);
            let mut rng = Rng::new(5);
            for f in 0..12 {
                let nbytes = rng.range_i32(300, 1800);
                let (ret, out) = e.encode(
                    &pcm[f * frame as usize * cu..(f + 1) * frame as usize * cu],
                    frame,
                    nbytes,
                );
                assert!(ret > 0);
                let pkt = &out[1..1 + ret as usize];
                #[cfg(not(feature = "disable-float-api"))]
                let mut pc = vec![0f32; frame as usize * cu];
                #[cfg(not(feature = "disable-float-api"))]
                let rc = cd.custom_decode_float(Some(pkt), ret, &mut pc, frame);
                #[cfg(not(feature = "disable-float-api"))]
                let mut pr = pc.clone();
                #[cfg(not(feature = "disable-float-api"))]
                let rr = rd.opus_custom_decode_float(Some(pkt), ret, &mut pr, frame);
                // DISABLE_FLOAT_API: 24-bit output.
                #[cfg(feature = "disable-float-api")]
                let mut pc = vec![0i32; frame as usize * cu];
                #[cfg(feature = "disable-float-api")]
                let rc = cd.custom_decode24(Some(pkt), ret, &mut pc, frame);
                #[cfg(feature = "disable-float-api")]
                let mut pr = pc.clone();
                #[cfg(feature = "disable-float-api")]
                let rr = rd.opus_custom_decode24(Some(pkt), ret, &mut pr, frame);
                code3 += usize::from(pkt[0] & 3 == 3);
                let ctx = format!(
                    "custom qext fs={fs} ch={ch} frame {f} (code3={})",
                    pkt[0] & 3 == 3
                );
                assert_eq!(code(rr), rc, "{ctx}");
                #[cfg(not(feature = "disable-float-api"))]
                assert_bits_eq_f32(&ctx, &pr, &pc);
                #[cfg(feature = "disable-float-api")]
                assert_slice_eq(&ctx, &pr, &pc);
                assert_state_eq(&ctx, &rust_state(&rd), &cd.state());
            }
        }
    }
    assert!(code3 > 20, "code-3 QEXT packets: {code3}");
}

/// Rough speed comparison with the C decoder (run with `--ignored --nocapture`).
#[test]
#[ignore = "timing only"]
fn perf_vs_c() {
    use std::time::Instant;
    let mut cfg = EncCfg::new(2, 960, 1275, Sig::Music);
    cfg.vbr_bitrate = 128000;
    let pkts = gen_packets(&cfg, 500, 1);
    let mut r = CeltDecoder::celt_decoder_init(48000, 2).unwrap();
    r.set_signalling(0);
    let mut cd = c::CeltDec::new(48000, 2).unwrap();
    cd.ctl_set(CELT_SET_SIGNALLING_REQUEST, 0);
    let mut pcm = vec![Res::default(); 1920];
    for _ in 0..3 {
        let t = Instant::now();
        for (m, _) in &pkts {
            cd.decode(Some(m), m.len() as i32, &mut pcm, 960, false, None);
        }
        let tc = t.elapsed();
        let t = Instant::now();
        for (m, _) in &pkts {
            r.celt_decode_with_ec(Some(m), m.len() as i32, &mut pcm, 960, None, false)
                .unwrap();
        }
        let tr = t.elapsed();
        println!(
            "C {tc:?}  Rust {tr:?}  ratio {:.2}",
            tr.as_secs_f64() / tc.as_secs_f64()
        );
    }
}
